<script setup lang="ts">
import {computed} from 'vue'
import {qualityGroups,latestServices,downloadEvidence,attemptObservedAt,latencyReadComplete,type QualityEvidence} from '../nodeQuality'
import {date,downloadSpeed,downloadTone,outcomeLabel,type ServiceRule} from '../domain'
import {downloadGroup,servicePassed,serviceAvailability} from '../sharedResults'
import {attemptStatus,attemptTone,downloadConditionLabel} from '../measurementRounds'
const props=defineProps<{evidence?:QualityEvidence;target:string;error?:string;catalog:ServiceRule[];expanded?:boolean;comparisonField?:'distribution'|'response'|'download'|'service'|'time'|'details';project?:'latency'|'download'|'service'|'combined'}>()
const groups=computed(()=>props.evidence?qualityGroups(props.evidence.tests,props.evidence.monitor,props.target):[])
const current=computed(()=>groups.value[0]),downloads=computed(()=>downloadEvidence(props.evidence?.downloads||[]))
const download=computed(()=>downloads.value.latest),validDownload=computed(()=>downloads.value.valid),speed=computed(()=>downloadSpeed(validDownload.value))
const services=computed(()=>latestServices(props.evidence?.services||[]))
const downloadTitle=computed(()=>[download.value?'最近检测：'+downloadConditionLabel(download.value):'',validDownload.value?'最近有效：'+downloadGroup(validDownload.value).label:''].filter(Boolean).join('\n'))
const readNames:Record<string,string>={latency:'延迟',monitor:'旧监测',download:'下载',service:'服务'}
const ms=(v:number|null|undefined)=>v===null||v===undefined?'—':Math.round(v)+' ms'
const title=computed(()=>current.value?`${current.value.source} · ${current.value.method} · ${current.value.target}\n条件：${current.value.condition}`:'无已保存样本')
const isSingle=computed(()=>!!props.project&&props.project!=='combined'&&!props.comparisonField)
const showLatency=computed(()=>(!props.project||props.project==='latency'||props.project==='combined')&&(!props.comparisonField||props.comparisonField==='distribution'||props.comparisonField==='response'))
const showDownload=computed(()=>(!props.project||props.project==='download'||props.project==='combined')&&(!props.comparisonField||props.comparisonField==='download'))
const showServices=computed(()=>(!props.project||props.project==='service'||props.project==='combined')&&(!props.comparisonField||props.comparisonField==='service'))
const rateTone=(rate:number|null|undefined,success:number)=>{if(rate===null||rate===undefined)return 'muted';if(success===0||rate===0)return 'bad';if(rate>=90)return 'good';if(rate>=50)return 'warn';return 'bad'}
const latencyTone=(val:number|null|undefined,success:number,source?:string)=>{if(success===0||val===null||val===undefined)return 'muted';if(source==='monitor'){if(val<150)return 'good';if(val<300)return 'good';if(val<600)return 'warn';return 'bad'}if(val<600)return 'good';if(val<900)return 'warn';return 'bad'}
const speedTone=(v:number|null|undefined)=>{if(v===null||v===undefined)return 'muted';if(v>=10)return 'good';if(v>=2)return 'warn';return 'bad'}
const downloadStatusTone=(a?:any)=>{if(!a)return 'muted';const t=downloadTone(a);return t==='empty'?'muted':t}
const serviceItemTone=(a?:any)=>{if(!a?.result)return 'muted';if(servicePassed(a))return 'good';if(serviceAvailability(a)===0||a.result.outcome==='http_rejected')return 'bad';const t=attemptTone(a);return t==='empty'?'muted':t}
</script>
<template><div class="quality-metrics" :class="{expanded,'comparison-field':comparisonField,'single-project':isSingle,['project-'+(project||'combined')]:true}"><template v-if="comparisonField&&(!evidence||error)"><strong class="muted">{{error?'读取失败 · 不可比较':'读取保存记录…'}}</strong><small v-if="error">{{error}}</small></template><template v-else>
 <section v-if="showLatency" class="quality-latency" :title="title"><template v-if="error"><strong class="bad">读取失败</strong><small>{{error}}</small></template><template v-else-if="!evidence"><strong class="muted">读取保存记录…</strong></template><template v-else-if="!current||!current.total"><strong class="muted">未测</strong><small>{{current?.excluded?'仅取消 / 条件不足记录，未计入样本':'所选站点无历史样本'}}</small></template><template v-else><div v-if="!comparisonField||comparisonField==='response'"><span class="metric-caption">成功率</span><strong :class="rateTone(current.successRate,current.success)">响应成功 {{current.successRate===null?'—':current.successRate.toFixed(0)+'%'}}</strong><span class="quality-secondary">{{current.success}} / {{current.total}} 样本</span><span v-if="current.success===0" class="badge bad">全数超时</span><span v-else-if="current.successRate!==null&&current.successRate<50" class="badge bad">高丢包 · 纸面参考</span><span v-else-if="current.insufficient&&current.success>0" class="warn">样本偏少</span></div><div v-if="!comparisonField||comparisonField==='distribution'"><span class="metric-caption">中位</span><strong :class="latencyTone(current.p50,current.success,current.source)">P50 {{ms(current.p50)}}</strong><span class="quality-secondary"><span class="metric-caption">最慢</span><strong v-if="current.success>=20" :class="latencyTone(current.p95,current.success,current.source)">P95 {{ms(current.p95)}}</strong><span v-else class="muted">P95 样本不足</span></span></div><small v-if="!comparisonField">{{date(current.lastAt)}} · {{current.source==='monitor'?'持续探测 (旧监测 RTT)':current.method==='http_get_via_proxy_first_byte'?'网页响应 (HTTP 首字节)':'方法 '+current.method}}<span v-if="groups.length>1"> · {{groups.length}} 组条件（显示最新组）</span></small><small v-if="current.insufficient&&current.comparable&&evidence&&latencyReadComplete(evidence,current)" class="warn">{{current.success?'样本较少 · 仅供参考，稳定性未确认':'全数请求超时，暂无有效延迟'}}</small><small v-if="!current.comparable" class="warn">不可比较 · 出口条件证据不足</small></template><small v-if="evidence&&current&&!latencyReadComplete(evidence,current)" class="warn">{{current.source==='monitor'?'旧监测':'延迟'}}读取不完整 · 不可比较</small><small v-if="evidence&&!current&&(!evidence.reads.latency.complete||!evidence.reads.monitor.complete)" class="warn">延迟/监测记录读取不完整 · 未测状态未确认</small></section>
 <section v-if="showDownload" class="quality-download" :title="downloadTitle"><strong>最近检测：<span class="badge" :class="downloadStatusTone(download)">{{download?attemptStatus(download,true):'未测'}}</span></strong><small v-if="download">{{date(attemptObservedAt(download))}} · {{download.rule.method||'方法未知'}} / v{{download.rule.rule_version??'?'}}</small><small v-if="validDownload">{{validDownload.attempt_id===download?.attempt_id?'最近有效速度':'历史有效速度'}}：<strong :class="speedTone(speed)">{{speed!.toFixed(2)}} MiB/s</strong> · {{downloadGroup(validDownload).kind==='partial'?'限时部分 (有效部分)':'完整读取'}} · {{date(attemptObservedAt(validDownload))}}</small><small v-else class="muted">无有效速度（暂无测速记录）</small><small v-if="evidence&&!evidence.reads.download.complete" class="warn">下载读取不完整 · 最近状态/速度未确认{{comparisonField?' · 不可比较':''}}</small><small v-if="comparisonField&&download" class="comparison-condition">最近检测条件：{{downloadConditionLabel(download)}}</small><small v-if="comparisonField&&validDownload" class="comparison-condition">{{validDownload.attempt_id===download?.attempt_id?'速度条件':'历史速度条件'}}：{{downloadGroup(validDownload).label}}</small></section>
 <section v-if="showServices" class="quality-services"><strong>服务检测 {{services.length?'（最近有记录 '+services.length+' 项）':'：未测'}}</strong><small v-for="a in services.slice(0,expanded||comparisonField==='service'||props.project==='service'?services.length:2)" :key="a.service_id||a.rule.service_id">{{catalog.find(s=>s.service_id===(a.service_id||a.rule.service_id))?.name||a.service_id||a.rule.service_id}}：<strong :class="serviceItemTone(a)">{{a.result?.outcome==='not_executed'?'未执行':a.result?outcomeLabel(a.result.outcome):attemptStatus(a)}}</strong> · {{date(attemptObservedAt(a))}}</small><small v-if="evidence&&!evidence.reads.service.complete" class="warn">服务读取不完整 · 最近结论未确认{{comparisonField?' · 不可比较':''}}</small></section>
 <section v-if="comparisonField==='time'" class="quality-times"><small>延迟：<time v-if="current" :datetime="current.lastAt">{{date(current.lastAt)}}</time><span v-else>未测</span></small><small>下载：<time v-if="download" :datetime="attemptObservedAt(download)">{{date(attemptObservedAt(download))}}</time><span v-else>未测</span></small><small v-if="validDownload&&validDownload.attempt_id!==download?.attempt_id">历史有效：<time :datetime="attemptObservedAt(validDownload)">{{date(attemptObservedAt(validDownload))}}</time></small><small v-for="a in services" :key="a.service_id||a.rule.service_id">{{catalog.find(s=>s.service_id===(a.service_id||a.rule.service_id))?.name||a.service_id||a.rule.service_id}}：<time :datetime="attemptObservedAt(a)">{{date(attemptObservedAt(a))}}</time></small><small v-if="!services.length">服务：未测</small></section>
 <details v-if="(expanded||comparisonField==='details')&&(!comparisonField||comparisonField==='details')&&evidence" class="quality-evidence-details"><summary>分组依据、样本与边界</summary><p>固定窗口 {{date(evidence.since)}} — {{date(evidence.until)}}；{{evidence.complete?'已读完窗口内保存记录':'读取不完整'}}。响应成功率不代表业务可用。P95 至少 20 个成功样本才在列表展示；5 个以下成功样本标为样本不足。波动为成功时延的总体标准差。</p><p v-for="(status,kind) in evidence.reads" :key="kind">{{readNames[kind]}}历史：{{status.complete?'读取完整':'读取不完整'}}{{status.error?' · '+status.error:''}}</p><article v-for="g in groups" :key="g.key"><strong>{{g.source}} · {{g.method}}</strong><p>{{g.target}} · {{g.success}}/{{g.total}} · P50 {{ms(g.p50)}} · P95 描述值 {{ms(g.p95)}} · 波动 {{ms(g.jitter)}} · 排除取消/未执行 {{g.excluded}}</p><p>{{g.comparable?'方法与路径有记录；仅同条件组可比较':'不可比较：旧方法或路径条件缺失'}} · {{g.condition}}</p></article><p v-if="download">最近检测条件：{{downloadConditionLabel(download)}}</p><p v-if="validDownload">最近有效速度条件：{{downloadGroup(validDownload).label}}</p><p>没有综合评分；不同目标、来源、协议、方法、版本和出口条件不合并。节点地区取自名称/配置，不等于出口地区。</p></details>
</template></div></template>
